head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > preserveType]<br/>dataType='number' 또는 'text' 인 Key 에 값(Value) 설정 시 dataType 속성값에 맞게 자동 형변환을 할지 설정합니다.",
    "validation" : [        
        "미설정 및 false 설정 시 dataType 속성값에 관계없이 설정하는 데이터형에 맞게 데이터가 설정됩니다.",
        "true 설정 시 Key 의 dataType 속성값('number')에 맞게 숫자형으로 자동 형변환 되어 설정됩니다.",
        "숫자형으로 변환되지 않는 경우 문자형으로 설정됩니다.",        
        "바인드 된 컴포넌트 또는 메소드로 Key 의 값(Value) 설정 시에도 적용됩니다.",
        "JSON, Array 를 반환하는 get 계열의 메소드는 저장된 데이터형에 맞게 값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // 조건 설정       
    let properties = {               
        preserveType: con_preserveType.getText(),
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key id="key1" name="name1" dataType="number"></w2:key>';     
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[dm_data1]]></key1>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';       

    $p.data.create(strTarget);

	// input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');
}



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setJSON_number_onclick = function (e) {
    let jsonData = {key1:"111"};
    target1.setJSON(jsonData);    

    scwin.btn_getJSON_onclick();
};



scwin.btn_setJSON_text_onclick = function (e) {
	let jsonData = {key1:"test"};
    target1.setJSON(jsonData);    

    scwin.btn_getJSON_onclick();
};
